import{_ as e,o,c as a,a5 as n}from"./chunks/framework.BvXk9IVy.js";const h=JSON.parse('{"title":"为什么我又开始写博客了","description":"","frontmatter":{"title":"为什么我又开始写博客了"},"headers":[],"relativePath":"notes/why-blog-again.md","filePath":"notes/why-blog-again.md","lastUpdated":1791895356000}'),p={name:"notes/why-blog-again.md"};function i(s,t,r,l,d,_){return o(),a("div",null,[...t[0]||(t[0]=[n('<h1 id="为什么我又开始写博客了" tabindex="-1">为什么我又开始写博客了</h1><blockquote><p>写下来的东西，是给一段时间打的结。</p></blockquote><p>上一间书斋停在三年前。最后一篇的日期我到现在还记得，但我没去点开看——怕看见自己当时信誓旦旦说过什么。</p><h2 id="那次是怎么停的" tabindex="-1">那次是怎么停的</h2><p>不是因为忙。三年里我其实写过不少东西：一段调了很久的构建脚本、一个绕了两天才想明白的并发问题、某本书里让我坐了一会儿的句子。只是它们都留在本地的笔记软件里，没往外拿。</p><p>往外拿是有成本的。选一个主题、配一次图床、想一个配得上这次改动的提交信息。每一样都不难，加起来刚好够成为不写的理由。</p><h2 id="那现在为什么又写了" tabindex="-1">那现在为什么又写了</h2><p>真正的原因很朴素：我开始有点舍不得。</p><p>去年搬家整理硬盘，翻到一篇旧文，写的是某个夏天在做什么、卡在哪里、后来怎么绕过去。那些事我早就忘干净了，但读完之后，那个夏天又回来了一点。不是细节，是一种温度。</p><p>我记性不好。不写下来的东西，就等于没有发生过。所以写博客对我来说不是输出，是存档——<strong>我只是想在时间里多打几个结。</strong></p><p>这间书斋也就是这么来的：从选框架开始重新搭了一遍，尽量把门槛拆到最低，剩下的就是坐下来写。</p><h2 id="有几件东西我特意没装" tabindex="-1">有几件东西我特意没装</h2><ul><li><strong>没有评论区。</strong> 有话想说的人，可以发邮件。被公开看着写和被人搭话之间，我想留一点距离。</li><li><strong>没有阅读量统计。</strong> 数字是会反过来教人写字的，一旦知道哪类文章有人看，手就会往那个方向偏。</li><li><strong>没有推荐位和热门。</strong> 这里没有「更多」，只有已经写下的。</li></ul><p>不是清高，是怕。这些东西都很擅长把一件安静的事变得热闹，而热闹之后往往就是停更。</p><h2 id="打算写什么" tabindex="-1">打算写什么</h2><p>技术笔记为主，顺手记一些读书和生活。不追求成体系，也不打算追热点——真正会写下来的，都是我自己在某个下午真的被卡住过、或者真的被打动过的东西。</p><p>写得慢一点没关系。三年后如果这篇还能被我自己翻出来，那它就算写成了。</p>',17)])])}const c=e(p,[["render",i]]);export{h as __pageData,c as default};
